"""Generate custom_sentences/<lang>/assist_learner.yaml from learned templates (and custom commands)."""

from __future__ import annotations

import logging
from pathlib import Path
from typing import Any

import yaml
from homeassistant.config_entries import ConfigEntry
from homeassistant.core import HomeAssistant

from . import recognizer
from .commands.model import scope_sentence, slot_scope
from .const import CONF_LANGUAGE
from .players import list_players, player_list_values

_LOGGER = logging.getLogger(__name__)

HEADER = (
    "# Generated by Assist Learner - edits will be overwritten.\n"
    "# Manage in the Assist Learner panel (Settings -> Assist Learner).\n"
)
MUSIC_INTENT = "AssistLearnerPlayMedia"
COMMAND_INTENT = "AssistLearnerCustomCommand"


def sentences_path(hass: HomeAssistant, language: str) -> Path:
    return Path(hass.config.path("custom_sentences", recognizer.sentences_language(language), "assist_learner.yaml"))


def _stale_path(hass: HomeAssistant, language: str) -> Path | None:
    """Where versions before the variant fix wrote the file (HA never loaded it there unless equal)."""
    if recognizer.sentences_language(language) == language:
        return None
    return Path(hass.config.path("custom_sentences", language, "assist_learner.yaml"))


def build_document(
    language: str,
    learned: list[dict[str, Any]],
    commands: list[dict[str, Any]],
    player_values: list[dict[str, str]],
) -> dict[str, Any]:
    """Pure function: store rows -> YAML-able dict. Disabled items are omitted."""
    intents: dict[str, Any] = {}
    lists: dict[str, Any] = {}

    music_blocks = [
        {
            "sentences": [t["template"]],
            "slots": {"media_type": (t.get("slots") or {}).get("media_type", "track"), "template_id": t["id"]},
        }
        for t in learned
        if t.get("enabled", True)
    ]
    if music_blocks:
        intents[MUSIC_INTENT] = {"data": music_blocks}
        lists["track"] = {"wildcard": True}
        lists["artist"] = {"wildcard": True}
        lists["player"] = {"values": player_values or [{"in": "nowhere", "out": "none"}]}

    cmd_blocks = []
    for c in commands:
        if c.get("status") != "active" or not c.get("sentences"):
            continue
        slots = c.get("slots") or {}
        cmd_blocks.append(
            {
                "sentences": [scope_sentence(x, c["id"], set(slots)) for x in c["sentences"]],
                "slots": {"command_id": c["id"]},
            }
        )
        for name, sdef in slots.items():
            if sdef["type"] == "number":
                lists[slot_scope(c["id"], name)] = {
                    "range": {"from": int(sdef["min"]), "to": int(sdef["max"]), "step": int(sdef.get("step", 1))}
                }
            else:
                lists[slot_scope(c["id"], name)] = {"values": list(sdef["values"])}
    if cmd_blocks:
        intents[COMMAND_INTENT] = {"data": cmd_blocks}

    doc: dict[str, Any] = {"language": recognizer.sentences_language(language)}
    if intents:
        doc["intents"] = intents
    if lists:
        doc["lists"] = lists
    return doc


async def async_write_sentences(hass: HomeAssistant, entry: ConfigEntry) -> Path:
    """Regenerate the file from the stores and reload conversation sentences."""
    store = entry.runtime_data.store
    language = entry.data[CONF_LANGUAGE]
    doc = build_document(
        language,
        store.learned.values(),
        store.commands.values(),
        player_list_values(list_players(hass)),
    )
    path = sentences_path(hass, language)
    text = HEADER + yaml.safe_dump(doc, sort_keys=False, allow_unicode=True)

    def _write() -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".yaml.tmp")
        tmp.write_text(text, encoding="utf-8")
        tmp.replace(path)
        if (stale := _stale_path(hass, language)) is not None and stale.exists():
            stale.unlink()

    await hass.async_add_executor_job(_write)
    await recognizer.async_reload(hass, language)
    return path
